func mtText(text *port.Cells, n int32) int32 {
	var i int32 = 0
	for i < n {
		model.TextAppendCp(text, 97)
		i += 1
	}
	return 0
}

func mtTree(nodes *port.Cells, attrs *port.Cells, regions *port.Cells, text *port.Cells, pages *port.Cells, ledger *port.Cells, layout *port.Cells) int32 {
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	model.NodeNew(nodes, model.NkSection(), 0)
	model.NodeNew(nodes, model.NkHeading(), 1)
	model.NodeNew(nodes, model.NkParagraph(), 1)
	model.NodeNew(nodes, model.NkText(), 3)
	model.NodeNew(nodes, model.NkSpan(), 3)
	model.NodeNew(nodes, model.NkText(), 5)
	model.NodeNew(nodes, model.NkList(), 1)
	model.NodeNew(nodes, model.NkItem(), 7)
	model.NodeNew(nodes, model.NkItem(), 7)
	model.NodeNew(nodes, model.NkSection(), 0)
	return 0
}

