func TestAttributesSetReplaceAndRepeat(emonT *testing.T) {
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var a int32 = 0
	mtTree(nodes, attrs, regions, text, pages, ledger, layout)
	mtText(text, 20)
	port.AssertEq(emonT, model.NodeAttr(nodes, attrs, 2, model.FkLevel()), -1, "no attribute yet")
	port.AssertEq(emonT, model.NodeAttrIntOr(nodes, attrs, 2, model.FkLevel(), 77), 77, "default when absent")
	model.NodeSetAttrInt(nodes, attrs, 2, model.FkLevel(), 4)
	model.NodeSetAttrText(nodes, attrs, 2, model.FkLabel(), 10, 6)
	model.NodeSetAttrNode(nodes, attrs, 2, model.FkTarget(), 7)
	model.NodeSetAttrBool(nodes, attrs, 2, model.FkChecked(), 5)
	port.AssertEq(emonT, model.AttrCount(attrs), 4, "four attributes")
	port.AssertEq(emonT, model.NodeAttrHead(nodes, 2), 0, "head is the first")
	a = model.NodeAttr(nodes, attrs, 2, model.FkLabel())
	port.AssertEq(emonT, a, 1, "label is attr 1")
	port.AssertEq(emonT, model.AttrKey(attrs, a), model.FkLabel(), "key")
	port.AssertEq(emonT, model.AttrVkind(attrs, a), model.AvText(), "a text value")
	port.AssertEq(emonT, model.AttrValue(attrs, a), 10, "run start")
	port.AssertEq(emonT, model.AttrLen(attrs, a), 6, "run length")
	port.AssertEq(emonT, model.AttrNext(attrs, a), 2, "chain order is insertion order")
	a = model.NodeAttr(nodes, attrs, 2, model.FkTarget())
	port.AssertEq(emonT, model.AttrVkind(attrs, a), model.AvNode(), "a node value")
	port.AssertEq(emonT, model.AttrValue(attrs, a), 7, "target node")
	a = model.NodeAttr(nodes, attrs, 2, model.FkChecked())
	port.AssertEq(emonT, model.AttrVkind(attrs, a), model.AvBool(), "a bool value")
	port.AssertEq(emonT, model.AttrValue(attrs, a), 1, "non-zero is stored as 1")
	port.AssertEq(emonT, model.AttrNext(attrs, a), -1, "the chain ends")
	model.NodeSetAttrInt(nodes, attrs, 2, model.FkLevel(), 5)
	port.AssertEq(emonT, model.AttrCount(attrs), 4, "set replaced in place")
	port.AssertEq(emonT, model.NodeAttrIntOr(nodes, attrs, 2, model.FkLevel(), 77), 5, "the new value")
	model.NodeSetAttrText(nodes, attrs, 2, model.FkLevel(), 3, 2)
	port.AssertEq(emonT, model.AttrVkind(attrs, 0), model.AvText(), "set may change the value kind")
	port.AssertEq(emonT, model.AttrLen(attrs, 0), 2, "and the length")
	model.NodeSetAttrBool(nodes, attrs, 2, model.FkChecked(), 0)
	port.AssertEq(emonT, model.NodeAttrIntOr(nodes, attrs, 2, model.FkChecked(), 9), 0, "false is 0")
	model.NodeAddAttrInt(nodes, attrs, 7, model.FkPages(), 1)
	model.NodeAddAttrInt(nodes, attrs, 7, model.FkPages(), 2)
	model.NodeAddAttrInt(nodes, attrs, 7, model.FkPages(), 9)
	model.NodeAddAttrText(nodes, attrs, 7, model.FkLabels(), 0, 1)
	port.AssertEq(emonT, model.AttrCount(attrs), 8, "add always appends")
	a = model.NodeAttr(nodes, attrs, 7, model.FkPages())
	port.AssertEq(emonT, model.AttrValue(attrs, a), 1, "first of the repeated key")
	a = model.AttrFindNext(attrs, a, model.FkPages())
	port.AssertEq(emonT, model.AttrValue(attrs, a), 2, "second")
	a = model.AttrFindNext(attrs, a, model.FkPages())
	port.AssertEq(emonT, model.AttrValue(attrs, a), 9, "third")
	port.AssertEq(emonT, model.AttrFindNext(attrs, a, model.FkPages()), -1, "no fourth")
	port.AssertEq(emonT, model.NodeAttr(nodes, attrs, 7, model.FkAlt()), -1, "a key never set")
	port.AssertEq(emonT, model.NodeAttr(nodes, attrs, 3, model.FkPages()), -1, "another node's chain is its own")
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, port.NewCells()), 0, "well formed")
}

func TestTextArenaHoldsScalarValuesOnly(emonT *testing.T) {
	var text *port.Cells = port.NewCells()
	port.AssertEq(emonT, model.TextAppendCp(text, 72), 0, "index written")
	port.AssertEq(emonT, model.TextAppendCp(text, 233), 1, "index written")
	model.TextAppendCp(text, 128512)
	model.TextAppendCp(text, -1)
	model.TextAppendCp(text, 55296)
	model.TextAppendCp(text, 57343)
	model.TextAppendCp(text, 1114111)
	model.TextAppendCp(text, 1114112)
	model.TextAppendCp(text, 0)
	port.AssertEq(emonT, model.TextLen(text), 9, "nine cells")
	port.AssertEq(emonT, model.TextAt(text, 0), 72, "H")
	port.AssertEq(emonT, model.TextAt(text, 1), 233, "e acute")
	port.AssertEq(emonT, model.TextAt(text, 2), 128512, "a code point past the BMP is one cell")
	port.AssertEq(emonT, model.TextAt(text, 3), 65533, "negative becomes U+FFFD")
	port.AssertEq(emonT, model.TextAt(text, 4), 65533, "a high surrogate becomes U+FFFD")
	port.AssertEq(emonT, model.TextAt(text, 5), 65533, "a low surrogate becomes U+FFFD")
	port.AssertEq(emonT, model.TextAt(text, 6), 1114111, "U+10FFFF is kept")
	port.AssertEq(emonT, model.TextAt(text, 7), 65533, "past U+10FFFF becomes U+FFFD")
	port.AssertEq(emonT, model.TextAt(text, 8), 0, "NUL is a scalar value")
}

func TestUtf8ValidAndInvalidSequences(emonT *testing.T) {
	var text *port.Cells = port.NewCells()
	var n int32 = model.TextAppendUtf8(text, port.HexBlob("41c3a9e282acf09f988080c0e080eda080f4908080 41"), 0, 22)
	port.AssertEq(emonT, n, 16, "sixteen code points: four good, eleven replacements, one more")
	port.AssertEq(emonT, model.TextLen(text), 16, "and sixteen cells")
	port.AssertEq(emonT, model.TextAt(text, 0), 65, "ASCII")
	port.AssertEq(emonT, model.TextAt(text, 1), 233, "two bytes")
	port.AssertEq(emonT, model.TextAt(text, 2), 8364, "three bytes")
	port.AssertEq(emonT, model.TextAt(text, 3), 128512, "four bytes")
	port.AssertEq(emonT, model.TextAt(text, 4), 65533, "a stray continuation byte")
	port.AssertEq(emonT, model.TextAt(text, 5), 65533, "C0 is never a lead")
	port.AssertEq(emonT, model.TextAt(text, 6), 65533, "E0 followed by 80 is overlong: E0 is one replacement")
	port.AssertEq(emonT, model.TextAt(text, 7), 65533, "and the 80 is a stray")
	port.AssertEq(emonT, model.TextAt(text, 8), 65533, "ED A0 is a surrogate: ED is one replacement")
	port.AssertEq(emonT, model.TextAt(text, 9), 65533, "A0 is a stray")
	port.AssertEq(emonT, model.TextAt(text, 10), 65533, "80 is a stray")
	port.AssertEq(emonT, model.TextAt(text, 11), 65533, "F4 90 is past U+10FFFF: F4 is one replacement")
	port.AssertEq(emonT, model.TextAt(text, 12), 65533, "90 is a stray")
	port.AssertEq(emonT, model.TextAt(text, 13), 65533, "80 is a stray")
	port.AssertEq(emonT, model.TextAt(text, 14), 65533, "80 is a stray")
	port.AssertEq(emonT, model.TextAt(text, 15), 65, "decoding resumes")
}

func TestUtf8TruncationAndSpans(emonT *testing.T) {
	var text *port.Cells = port.NewCells()
	var n1 int32 = model.TextAppendUtf8(text, port.HexBlob("41e282"), 0, 3)
	var n2 int32 = model.TextAppendUtf8(text, port.HexBlob("41c3a942"), 1, 3)
	var n3 int32 = model.TextAppendUtf8(text, port.HexBlob("f09f98"), 0, 3)
	var n4 int32 = model.TextAppendUtf8(text, port.HexBlob("f09f9880"), 0, 0)
	port.AssertEq(emonT, n1, 2, "A, then a cut-short three-byte sequence is one replacement")
	port.AssertEq(emonT, n2, 1, "the span is [1,3): just the two bytes of e acute")
	port.AssertEq(emonT, n3, 1, "a cut-short four-byte sequence is one replacement")
	port.AssertEq(emonT, n4, 0, "an empty span")
	port.AssertEq(emonT, model.TextLen(text), 4, "four cells in all")
	port.AssertEq(emonT, model.TextAt(text, 0), 65, "A")
	port.AssertEq(emonT, model.TextAt(text, 1), 65533, "replacement")
	port.AssertEq(emonT, model.TextAt(text, 2), 233, "e acute")
	port.AssertEq(emonT, model.TextAt(text, 3), 65533, "replacement")
}

