func TestCheckNamesEachWayAModelCanBeWrong(emonT *testing.T) {
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	mtTree(nodes, attrs, regions, text, pages, ledger, layout)
	model.TextAppendCp(text, 65)
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "well formed to begin with")
	port.CellsPush(nodes, 0)
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), model.McBadStride(), "a stray cell")
	mtTree(nodes, attrs, regions, text, pages, ledger, layout)
	port.CellsSet(nodes, 17, 99)
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), model.McBadLink(), "a parent out of range")
	port.AssertEq(emonT, port.CellsAt(st, 0), 1, "names node 1")
	mtTree(nodes, attrs, regions, text, pages, ledger, layout)
	port.CellsSet(nodes, (3*16)+1, 2)
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), model.McBadTree(), "a child that points at another parent")
	mtTree(nodes, attrs, regions, text, pages, ledger, layout)
	port.CellsSet(nodes, (3*16)+7, 0)
	port.CellsSet(nodes, (3*16)+8, 5)
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), model.McBadText(), "a text run past the arena")
	port.AssertEq(emonT, port.CellsAt(st, 0), 3, "names node 3")
	mtTree(nodes, attrs, regions, text, pages, ledger, layout)
	model.NodeSetConf(nodes, 3, 10)
	port.CellsSet(nodes, (3*16)+12, 1001)
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), model.McBadConf(), "a confidence of 1001")
	mtTree(nodes, attrs, regions, text, pages, ledger, layout)
	port.CellsSet(nodes, 0, 2)
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), model.McNoRoot(), "a root that is not a document")
	mtTree(nodes, attrs, regions, text, pages, ledger, layout)
	port.CellsSet(nodes, (4*16)+0, 40)
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), 3, "an unknown kind is mc-bad-kind")
	mtTree(nodes, attrs, regions, text, pages, ledger, layout)
	model.NodeSetAttrText(nodes, attrs, 3, model.FkLabel(), 0, 4)
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), model.McBadAttr(), "an attribute run past the arena")
	mtTree(nodes, attrs, regions, text, pages, ledger, layout)
	model.NodeAddRegion(nodes, regions, 3, 1, 0, 0, 1, 1)
	port.CellsSet(nodes, (3*16)+10, 2)
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), model.McBadRegion(), "a region count that is not the chain")
	mtTree(nodes, attrs, regions, text, pages, ledger, layout)
	model.PageNew(pages, 1, 100, 100, 0, 1)
	model.PageSetLabel(pages, 0, 0, 3)
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), model.McBadPage(), "a page label past the arena")
	mtTree(nodes, attrs, regions, text, pages, ledger, layout)
	model.LedgerAdd(ledger, 1, 1, 0, 0, 1, 1, 2000, 0)
	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), model.McBadLedger(), "a ledger confidence of 2000")
}

