	port.AssertEq(emonT, model.LayAdd(layout, pages, 1, 0, 1, 3, 0, 0, 1, 1), -1, "a role that is no layout role")
	port.AssertEq(emonT, model.LayAdd(layout, pages, 2, 0, 0, model.RlBody(), 0, 0, 1, 1), -1, "no such page")
