	port.AssertEq(emonT, model.LayoutBand(layout, 1), 0, "band")
	port.AssertEq(emonT, model.LayoutCol(layout, 1), 1, "col")
	port.AssertEq(emonT, model.LayoutRole(layout, 1), 9, "role")
	port.AssertEq(emonT, model.LayoutX0(layout, 1), 31200, "x0")
	port.AssertEq(emonT, model.LayoutY0(layout, 1), 9000, "y0")
	port.AssertEq(emonT, model.LayoutX1(layout, 1), 54000, "x1")
	port.AssertEq(emonT, model.LayoutY1(layout, 1), 75000, "y1")
