	port.AssertEq(emonT, model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, st), model.McBadLayout(), "a run past the arena")
	port.CellsSet(pages, 12, 2)
	port.CellsSet(layout, 3, 3)
